def icon(name, cls="h-6 w-6"):
    if name == "whatsapp":
        return WHATSAPP.format(cls=cls)
    if name in FILLED:
        return f'<svg viewBox="0 0 24 24" fill="currentColor" class="{cls}" aria-hidden="true">{FILLED[name]}</svg>'
    return (f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" '
            f'stroke-linejoin="round" class="{cls}" aria-hidden="true">{ICONS[name]}</svg>')


